pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address player, bytes32 hash, uint256 sentWei) public {
        // Restrict player to non-zero address and sentWei to a reasonable range
        vm.assume(player != address(0));
        sentWei = bound(sentWei, 0, 2 ether);

        // Fund the player and give ether to the contract for the initial 1 ether requirement
        vm.deal(player, 10 ether);

        // Before lockInGuess, record the contract's balance and player's balance
        uint256 balanceBefore = address(c).balance;

        // Drive the call to lockInGuess with the given msg.value
        vm.prank(player);
        (bool success, ) = address(c).call{value: sentWei}(abi.encodeWithSelector(c.lockInGuess.selector, hash));

        // After call, check the difference in contract balance
        uint256 balanceAfter = address(c).balance;

        // General rule: if the call succeeded, the contract balance increased by exactly sentWei
        // (because the contract deducts nothing from its own balance).
        // For the reference, the require reverts if sentWei != 1 ether, so if it succeeds,
        // the balance increase is exactly 1 ether.
        // For the mutant, the require is removed, so any sentWei will succeed, and the balance
        // increase equals sentWei (which can be anything). Thus the rule "balance increase == 1 ether"
        // holds for reference but not for mutant when sentWei != 1 ether.
        if (success) {
            assertTrue(balanceAfter - balanceBefore == 1 ether, "Balance increase should be exactly 1 ether");
        } else {
            // If it reverted, balance should be unchanged (by solidity semantics)
            assertTrue(balanceAfter == balanceBefore, "Balance unchanged on revert");
        }
    }
}

