    function testFuzz_property(bytes32 guessHash) public {
        // Fund test accounts: deployer and caller
        vm.deal(address(this), 1 ether);
        vm.deal(address(0x1), 1 ether);

        // Call lockInGuess as address(0x1) with 1 ether
        vm.prank(address(0x1));
        c.lockInGuess{value: 1 ether}(guessHash);

        // Record the contract balance before settle
        uint256 balanceBefore = address(c).balance;

        // Attempt settle as address(0x1)
        vm.prank(address(0x1));
        c.settle();

        uint256 balanceAfter = address(c).balance;

        // The contract should never have paid out 2 ether when blockhash was zero
        // This occurs if balance decreased by 2 ether (the payout amount)
        assertTrue(balanceAfter >= balanceBefore || balanceBefore - balanceAfter != 2 ether);
    }
}

